@app.post("/settings/notifications", response_class=HTMLResponse)
def update_notification_settings_form(
    request: Request,
    user_id: int = Form(...),
    email_alerts: bool = Form(False),
    sms_alerts: bool = Form(False),
    db: Session = Depends(get_db)
):
    session_user = get_session_user(request)
    if not session_user:
        return RedirectResponse(url="/login")

    if user_id != session_user.id:
        raise HTTPException(status_code=403, detail="Cannot alter notification preferences of another user")

    prefs = db.query(UserPreferences).filter(UserPreferences.user_id == session_user.id).first()
    if not prefs:
        prefs = UserPreferences(user_id=session_user.id)
        db.add(prefs)

    prefs.email_alerts = email_alerts
    prefs.sms_alerts = sms_alerts
    db.commit()
    return templates.TemplateResponse("settings_saved.html", {"request": request, "prefs": prefs})
